// The two themes the React app shipped, ported value for value.
//
// Every colour here is lifted directly from the `:root` and
// `:root[data-theme="dark"]` blocks in src/App.css. Nothing is re-picked or
// "improved" — the point of this step is that the Flutter app is
// indistinguishable from the React one, so any later difference is a
// deliberate choice rather than drift.
//
// Each pack ships with a `_touch` sibling generated by `touchVariant`: same
// colours, roomier metrics. `PointerDensityTrigger` swaps between them, which
// is how a phone gets 44pt hit targets without a single widget branching on
// Platform.isIOS.

import 'package:flutter/material.dart';
import 'package:flutter_theme_engine/flutter_theme_engine.dart';

import 'link_health_colors.dart';
import 'websave_theme.dart';

/// `:root` — the light theme.
const daylight = WebSaveTheme(
  brightness: Brightness.light,
  background: Color(0xFFF6F6F8), // --bg
  panel: Color(0xFFFFFFFF), // --bg-panel
  border: Color(0xFFE0E0E6), // --border
  text: Color(0xFF1C1C21), // --text
  textDim: Color(0xFF6E6E78), // --text-dim
  accent: Color(0xFF4762FF), // --accent
  accentText: Color(0xFFFFFFFF), // --accent-text
  danger: Color(0xFFD4373E), // --danger
  states: InteractionColors(
    hover: Color(0xFFEDEDF1), // --bg-hover
    pressed: Color(0xFFE3E3EA), // --bg-active
    selected: Color(0xFFE3E3EA),
  ),
  health: LinkHealthColors(
    active: Color(0xFF2E9E5B), // --green
    changed: Color(0xFFC98A1B), // --amber
    redirected: Color(0xFF3578C9), // --blue
    unreachable: Color(0xFF8A6D3B), // muted amber: a warning, not a verdict
    dead: Color(0xFFD4373E), // --red
    unchecked: Color(0xFF9A9AA3), // --gray
  ),
  swatch: [Color(0xFFF6F6F8), Color(0xFF4762FF), Color(0xFF1C1C21)],
);

/// `:root[data-theme="dark"]` — the dark theme.
const midnight = WebSaveTheme(
  brightness: Brightness.dark,
  background: Color(0xFF161616),
  panel: Color(0xFF1E1E1E),
  border: Color(0xFF2D2D2D),
  text: Color(0xFFEDEDED),
  textDim: Color(0xFF9C9C9C),
  accent: Color(0xFF7C8CFF),
  accentText: Color(0xFFFFFFFF),
  danger: Color(0xFFE06363),
  states: InteractionColors(
    hover: Color(0xFF272727),
    pressed: Color(0xFF303030),
    selected: Color(0xFF303030),
  ),
  health: LinkHealthColors(
    active: Color(0xFF46B97A),
    changed: Color(0xFFD9A13B),
    redirected: Color(0xFF5E9FDD),
    unreachable: Color(0xFFBE9152),
    dead: Color(0xFFE06363),
    unchecked: Color(0xFF767676),
  ),
  swatch: [Color(0xFF161616), Color(0xFF7C8CFF), Color(0xFFEDEDED)],
);

/// Every pack the app registers.
///
/// The first is the fallback. Touch variants are generated rather than
/// authored, so a colour can never be corrected in one and forgotten in the
/// other — the whole reason `copyWith` exists for pack authors.
final webSavePacks = <ThemePack<WebSaveTheme>>[
  const ThemePack<WebSaveTheme>(
    id: 'daylight',
    meta: ThemeMeta(
      name: 'Daylight',
      description: 'The original light theme.',
      tags: ['light', 'default'],
    ),
    model: daylight,
  ),
  const ThemePack<WebSaveTheme>(
    id: 'midnight',
    meta: ThemeMeta(
      name: 'Midnight',
      description: 'The original dark theme.',
      tags: ['dark', 'default'],
    ),
    model: midnight,
  ),
  ThemePack<WebSaveTheme>(
    id: 'daylight_touch',
    meta: const ThemeMeta(
      name: 'Daylight (touch)',
      description: 'Daylight with room for a fingertip.',
      tags: ['light', 'touch'],
    ),
    model: daylight.touchVariant,
  ),
  ThemePack<WebSaveTheme>(
    id: 'midnight_touch',
    meta: const ThemeMeta(
      name: 'Midnight (touch)',
      description: 'Midnight with room for a fingertip.',
      tags: ['dark', 'touch'],
    ),
    model: midnight.touchVariant,
  ),
];
